import csv
import json
from flask import Flask, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

CSV_PATH = "uploads/sensor_readings.csv"

def read_csv():
    readings = []
    with open(CSV_PATH, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            readings.append({
                "timestamp": row["timestamp"],
                "sensor": row["sensor"],
                "temperature_c": float(row["temperature_c"])
            })
    return readings

@app.route("/api/readings")
def api_readings():
    return jsonify(read_csv())

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=3000)

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    host: '0.0.0.0',
    port: 8000,
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true
      }
    }
  }
})

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen,
    Ubuntu, Cantarell, sans-serif;
  background: #0f172a;
  color: #e2e8f0;
  min-height: 100vh;
  padding: 2rem;
}

.dashboard {
  max-width: 960px;
  margin: 0 auto;
}

h1 {
  font-size: 2rem;
  margin-bottom: 1.5rem;
  color: #f8fafc;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Summary cards */
.summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  margin-bottom: 2rem;
}

.card {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  padding: 1.25rem 1.5rem;
  text-align: center;
}

.card-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
  margin-bottom: 0.5rem;
}

.card-value {
  font-size: 1.75rem;
  font-weight: 700;
}

.card-value.count { color: #38bdf8; }
.card-value.min   { color: #4ade80; }
.card-value.max   { color: #fb923c; }

/* Table */
.table-wrapper {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  overflow: hidden;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead {
  background: #334155;
}

th {
  padding: 0.75rem 1rem;
  text-align: left;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #94a3b8;
  font-weight: 600;
}

td {
  padding: 0.65rem 1rem;
  border-top: 1px solid #1e293b;
  font-size: 0.9rem;
}

tbody tr:hover {
  background: #263044;
}

.sensor-tag {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 600;
  background: #334155;
  color: #cbd5e1;
}

.temp {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

/* Loading / error states */
.loading, .error {
  text-align: center;
  padding: 3rem;
  font-size: 1.1rem;
  color: #94a3b8;
}

.error { color: #f87171; }

@media (max-width: 600px) {
  .summary {
    grid-template-columns: 1fr;
  }
}
